    # Minimum number of seconds between two (non forced) status updates sent to the server.
    _UPDATE_INTERVAL = 10.0
    # Number of seconds a cached authentication token is considered valid before being re-read from disk.
    _TOKEN_CACHE_TTL = 60.0
