        headers = {"Content-Type": "application/json"}
        token = self._get_token()
        if token:
            headers["Authorization"] = f"Bearer {token}"

        if not self._ssl_context_initialized:
            if server_url.lower().startswith("https"):
                self._ssl_context = ssl.create_default_context()
            self._ssl_context_initialized = True

        request = urllib.request.Request(server_url, data=data, headers=headers, method="POST")
        try:
            if self._ssl_context is not None:
                urllib.request.urlopen(request, timeout=self._REQUEST_TIMEOUT, context=self._ssl_context)
            else:
                urllib.request.urlopen(request, timeout=self._REQUEST_TIMEOUT)
        except Exception as error:
            logger.warning(f"Could not report training status to the Kubeflow Trainer server at {server_url}: {error}")
            return False

        return True


